    apply (lap_of_run tm Cc true true cho_1RB0LB_1LA0RC_1RD0LA_1LD1RC B0_1RB0LB_1LA0RC_1RD0LA_1LD1RC B1_1RB0LB_1LA0RC_1RD0LA_1LD1RC 4 12 p j' [] []).
