      with (l := [SRotL 1; SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LB_1LA0RC_1RD0LA_1LD1RC
      with (l := [SRotL 1; SWin 3; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
