    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LB_1LA0RC_1RD0LA_1LD1RC
      with (l := [SRotL 1; SWin 3; SCycL 2 0; SWin 3; SWinL 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LB_1LA0RC_1RD0LA_1LD1RC
      with (l := [SRotL 1; SWin 3; SCycL 2 0; SWin 3; SWinL 3]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LB_1LA0RC_1RD0LA_1LD1RC
      with (l := [SRotL 1; SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LB_1LA0RC_1RD0LA_1LD1RC
