      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SWinL 4]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB0LB_1LA0RC_1RD0LB_0LC1RC : NeverQuasiHaltsTr tm_1RB0LB_1LA0RC_1RD0LB_0LC1RC.
