(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LB_1LB0LC_0RD1LC_1RD1RA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_11_00_01 q0 ++ [S0]) [] j A0_1RB0LB_1LB0LC_0RD1LC_1RD1RA.
Proof.
  intros p j q0 E. destruct (Alph_11_00_01.cview_some_Alph_11_00_01 p j q0 E) as (H1 & _).
  unfold Cc_1RB0LB_1LB0LC_0RD1LC_1RD1RA, cden, A0_1RB0LB_1LB0LC_0RD1LC_1RD1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S0] where the anchor has [S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB0LB_1LB0LC_0RD1LC_1RD1RA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_11_00_01 q0 ++ [S0]) [] j A1_1RB0LB_1LB0LC_0RD1LC_1RD1RA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_11_00_01.cview_some_Alph_11_00_01 p j q0 E) as (_ & H2).
  unfold Cc_1RB0LB_1LB0LC_0RD1LC_1RD1RA, cden, A1_1RB0LB_1LB0LC_0RD1LC_1RD1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S0]) with (([S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LB_1LB0LC_0RD1LC_1RD1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 12), (cden (Ap_Alph_11_00_01 q0 ++ [S0]) [] j A1_1RB0LB_1LB0LC_0RD1LC_1RD1RA).
  split; [lia|]. split; [| exact (gei_1RB0LB_1LB0LC_0RD1LC_1RD1RA p j q0 E)].
  rewrite (gsi_1RB0LB_1LB0LC_0RD1LC_1RD1RA p j q0 E).
  exact (srun_sound tm false true chi_1RB0LB_1LB0LC_0RD1LC_1RD1RA A0_1RB0LB_1LB0LC_0RD1LC_1RD1RA A1_1RB0LB_1LB0LC_0RD1LC_1RD1RA 4 12
           run_int_1RB0LB_1LB0LC_0RD1LC_1RD1RA (Ap_Alph_11_00_01 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB0LB_1LB0LC_0RD1LC_1RD1RA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LB_1LB0LC_0RD1LC_1RD1RA.
Proof.
