Definition AI0_1RB0LB_1LB1RC_1LA0RD_0RC0LB : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition AI1_1RB0LB_1LB1RC_1LA0RD_0RC0LB : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0;S1] [] 0 0 []).
Definition chn_1RB0LB_1LB1RC_1LA0RD_0RC0LB : list lstep := [SWin 8; SCycL 2 0; SWin 4; SCycR 2].

Lemma run_inner_1RB0LB_1LB1RC_1LA0RD_0RC0LB : srun tm false true chn_1RB0LB_1LB1RC_1LA0RD_0RC0LB AI0_1RB0LB_1LB1RC_1LA0RD_0RC0LB = Some (AI1_1RB0LB_1LB1RC_1LA0RD_0RC0LB, 4, 12).
