(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0LB_1LB1RC_1LA0RD_0RC0LB : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S0;S1;S1]) S0 (mkS [S0;S1] [] 0 0 []).
