(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0LB_1LB1RC_1LA0RD_0RC0LB.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB0LB_1LB1RC_1LA0RD_0RC0LB, cden, A0_1RB0LB_1LB1RC_1LA0RD_0RC0LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall p j q0, cview p = (j, Some q0) ->
  cden (Jp q0 ++ [S0]) [] j A1_1RB0LB_1LB1RC_1LA0RD_0RC0LB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_1RB0LB_1LB1RC_1LA0RD_0RC0LB, cden, A1_1RB0LB_1LB1RC_1LA0RD_0RC0LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 12). split; [lia|].
  rewrite (gsi_1RB0LB_1LB1RC_1LA0RD_0RC0LB p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0LB_1LB1RC_1LA0RD_0RC0LB A0_1RB0LB_1LB1RC_1LA0RD_0RC0LB A1_1RB0LB_1LB1RC_1LA0RD_0RC0LB 4 12
             run_int_1RB0LB_1LB1RC_1LA0RD_0RC0LB (Jp q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0LB_1LB1RC_1LA0RD_0RC0LB p j q0 E).
Qed.

Lemma gso_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0LB_1LB1RC_1LA0RD_0RC0LB.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_1RB0LB_1LB1RC_1LA0RD_0RC0LB, cden, B0_1RB0LB_1LB1RC_1LA0RD_0RC0LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LB_1LB1RC_1LA0RD_0RC0LB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0LB_1LB1RC_1LA0RD_0RC0LB
             = (StB, (rep [S1;S1] (S j) ++ [S1;S0], S0, [S0;S1]))).
  { unfold cden, B1_1RB0LB_1LB1RC_1LA0RD_0RC0LB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, (rep [S1;S1] (S j) ++ [S1;S0], S0, [S0;S1]))).
  { unfold Cc_1RB0LB_1LB1RC_1LA0RD_0RC0LB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. reflexivity.
Qed.

Lemma gsn_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Jp q0 ++ [S0;S1;S1]) [] i AI0_1RB0LB_1LB1RC_1LA0RD_0RC0LB.
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (H1 & _).
  unfold Cin_1RB0LB_1LB1RC_1LA0RD_0RC0LB, cden, AI0_1RB0LB_1LB1RC_1LA0RD_0RC0LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Jp q0 ++ [S0;S1;S1]) [] i AI1_1RB0LB_1LB1RC_1LA0RD_0RC0LB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (JpCounter.cview_some_J v i q0 E) as (_ & H2).
  unfold Cin_1RB0LB_1LB1RC_1LA0RD_0RC0LB, cden, AI1_1RB0LB_1LB1RC_1LA0RD_0RC0LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 12), (cden (Jp q0 ++ [S0;S1;S1]) [] i AI1_1RB0LB_1LB1RC_1LA0RD_0RC0LB).
  split; [lia|]. split; [| exact (gen_1RB0LB_1LB1RC_1LA0RD_0RC0LB v i q0 E)].
  rewrite (gsn_1RB0LB_1LB1RC_1LA0RD_0RC0LB v i q0 E).
  exact (srun_sound tm false true chn_1RB0LB_1LB1RC_1LA0RD_0RC0LB AI0_1RB0LB_1LB1RC_1LA0RD_0RC0LB AI1_1RB0LB_1LB1RC_1LA0RD_0RC0LB 4 12
           run_inner_1RB0LB_1LB1RC_1LA0RD_0RC0LB (Jp q0 ++ [S0;S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall j, lift (cden [] [] j BB1_1RB0LB_1LB1RC_1LA0RD_0RC0LB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LB_1LB1RC_1LA0RD_0RC0LB = (StB, (rep [S1;S1] j ++ [S1;S0;S1;S1], S0, [S0;S1]))).
  { unfold cden, BB1_1RB0LB_1LB1RC_1LA0RD_0RC0LB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S1] j ++ [S1;S0;S1;S1], S0, [S0;S1]))).
  { unfold Cin_1RB0LB_1LB1RC_1LA0RD_0RC0LB. rewrite epow2_1RB0LB_1LB1RC_1LA0RD_0RC0LB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LB_1LB1RC_1LA0RD_0RC0LB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LB_1LB1RC_1LA0RD_0RC0LB.
Proof.
  intro j.
  destruct (JpCounter.cview_none_J (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LB_1LB1RC_1LA0RD_0RC0LB, cden, BE0_1RB0LB_1LB1RC_1LA0RD_0RC0LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB0LB_1LB1RC_1LA0RD_0RC0LB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LB_1LB1RC_1LA0RD_0RC0LB p (pow2 j)).
  - exists (4 * j + 20), (cden [] [] j BB1_1RB0LB_1LB1RC_1LA0RD_0RC0LB).
    split; [lia|]. split; [| exact (gbo_1RB0LB_1LB1RC_1LA0RD_0RC0LB j)].
    rewrite (gso_1RB0LB_1LB1RC_1LA0RD_0RC0LB p j E).
    exact (srun_sound tm true true chb_1RB0LB_1LB1RC_1LA0RD_0RC0LB B0_1RB0LB_1LB1RC_1LA0RD_0RC0LB BB1_1RB0LB_1LB1RC_1LA0RD_0RC0LB 4 20
             run_boot_1RB0LB_1LB1RC_1LA0RD_0RC0LB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 16), (cden [] [] j B1_1RB0LB_1LB1RC_1LA0RD_0RC0LB).
    split; [| exact (geo_1RB0LB_1LB1RC_1LA0RD_0RC0LB p j E)].
    rewrite (gxi_1RB0LB_1LB1RC_1LA0RD_0RC0LB j).
    exact (srun_sound tm true true che_1RB0LB_1LB1RC_1LA0RD_0RC0LB BE0_1RB0LB_1LB1RC_1LA0RD_0RC0LB B1_1RB0LB_1LB1RC_1LA0RD_0RC0LB 4 16
             run_exit_1RB0LB_1LB1RC_1LA0RD_0RC0LB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LB_1LB1RC_1LA0RD_0RC0LB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LB_1LB1RC_1LA0RD_0RC0LB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LB_1LB1RC_1LA0RD_0RC0LB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 20.
  assert (H : match csteps tm 20 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 20 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LB_1LB1RC_1LA0RD_0RC0LB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LB_1LB1RC_1LA0RD_0RC0LB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LB_1LB1RC_1LA0RD_0RC0LB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LB_1LB1RC_1LA0RD_0RC0LB : forall t, ~ In t pins_1RB0LB_1LB1RC_1LA0RD_0RC0LB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0LB_1LB1RC_1LA0RD_0RC0LB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0LB_1LB1RC_1LA0RD_0RC0LB
      with (l := [SWin 8; SCycL 2 0; SWin 2; SWinL 2]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LB_1LB1RC_1LA0RD_0RC0LB
      with (l := [SWin 8; SCycL 2 0; SWin 2; SWinL 5]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LB_1LB1RC_1LA0RD_0RC0LB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0LB_1LB1RC_1LA0RD_0RC0LB
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LB_1LB1RC_1LA0RD_0RC0LB
      with (l := [SWin 8; SCycL 2 0; SWin 2; SWinL 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LB_1LB1RC_1LA0RD_0RC0LB
      with (l := [SWin 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LB_1LB1RC_1LA0RD_0RC0LB
      with (l := [SWin 8]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0LB_1LB1RC_1LA0RD_0RC0LB
      with (l := [SWin 4]).
