  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0LB_1LC0RC_1LA0RD_0RB1LB
      with (l := [SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0LB_1LC0RC_1LA0RD_0RB1LB
      with (l := []).
