    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0LB_1LC0RC_1LA0RD_0RB1LB
      with (l := [SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0LB_1LC0RC_1LA0RD_0RB1LB
      with (l := [SCycL 3 0; SWin 3; SWinL 4]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0LB_1LC0RC_1LA0RD_0RB1LB
      with (l := [SCycL 3 0; SWin 3; SWinL 5]).
