  exists (6 * j + 10), (cden (Ap_Alph_000_001_1 q0 ++ [S0]) [] j A1_1RB0LB_1LC1RD_0RB0LC_1RA1LD).
  split; [lia|]. split; [| exact (gei_1RB0LB_1LC1RD_0RB0LC_1RA1LD p j q0 E)].
  rewrite (gsi_1RB0LB_1LC1RD_0RB0LC_1RA1LD p j q0 E).
