Definition mk_1RB0LB_1LC1RD_0RD0LC_1RA0LA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0LB_1LC1RD_0RD0LC_1RA0LA.

(** 1RB0LB_1LC1RD_0RD0LC_1RA0LA *)
(** 1RB0LB_1LC1RD_0RD0LC_1RA0LA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LB_1LC1RD_0RD0LC_1RA0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StB
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S0 DL StC
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S0 DL StA end.

(** Its mirror 1LB0RB_1RC1LD_0LD0RC_1LA0RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LB_1LC1RD_0RD0LC_1RA0LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StB
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S0 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LB_1LC1RD_0RD0LC_1RA0LA : list Instr := [].
Definition tmw_1RB0LB_1LC1RD_0RD0LC_1RA0LA : TM := tm_wrap_trs tmm_1RB0LB_1LC1RD_0RD0LC_1RA0LA pins_1RB0LB_1LC1RD_0RD0LC_1RA0LA.
Local Notation tm := tmw_1RB0LB_1LC1RD_0RD0LC_1RA0LA.

Lemma mirror_ok_1RB0LB_1LC1RD_0RD0LC_1RA0LA : mirror_tm tm_1RB0LB_1LC1RD_0RD0LC_1RA0LA = tmm_1RB0LB_1LC1RD_0RD0LC_1RA0LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0LB_1LC1RD_0RD0LC_1RA0LA (p : positive) : cconf := (StB, (Ap_Alph_000_001_1 p ++ [S0], S0, [S1;S1])).
Local Notation Cc := Cc_1RB0LB_1LC1RD_0RD0LC_1RA0LA.

(** ** The certificate *)

