Lemma run_inner2_1RB0LB_1LC1RD_0RD0LC_1RA0LA : srun tm false true chn2_1RB0LB_1LC1RD_0RD0LC_1RA0LA AI20_1RB0LB_1LC1RD_0RD0LC_1RA0LA = Some (AI21_1RB0LB_1LC1RD_0RD0LC_1RA0LA, 6, 6).
