Lemma gen_1RB0LB_1LC1RD_0RD0LC_1RA0LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_000_001_00 q0 ++ [S0;S0;S1]) [] i AI1_1RB0LB_1LC1RD_0RD0LC_1RA0LA) = lift (Cin (Pos.succ v)).
