Lemma lapin_1RB0LB_1LC1RD_0RD0LC_1RA0LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 6), (cden (Ap_Alph_000_001_00 q0 ++ [S0;S0;S1]) [] i AI1_1RB0LB_1LC1RD_0RD0LC_1RA0LA).
  split; [lia|]. split; [| exact (gen_1RB0LB_1LC1RD_0RD0LC_1RA0LA v i q0 E)].
  rewrite (gsn_1RB0LB_1LC1RD_0RD0LC_1RA0LA v i q0 E).
  exact (srun_sound tm false true chn_1RB0LB_1LC1RD_0RD0LC_1RA0LA AI0_1RB0LB_1LC1RD_0RD0LC_1RA0LA AI1_1RB0LB_1LC1RD_0RD0LC_1RA0LA 6 6
           run_inner_1RB0LB_1LC1RD_0RD0LC_1RA0LA (Ap_Alph_000_001_00 q0 ++ [S0;S0;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB0LB_1LC1RD_0RD0LC_1RA0LA : forall j, lift (cden [] [] j BB1_1RB0LB_1LC1RD_0RD0LC_1RA0LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LB_1LC1RD_0RD0LC_1RA0LA = (StC, (rep [S0;S0;S0] j ++ [S0;S0;S0;S0;S1], S0, []))).
  { unfold cden, BB1_1RB0LB_1LC1RD_0RD0LC_1RA0LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S0;S0;S0] j ++ [S0;S0;S0;S0;S1], S0, []))).
  { unfold Cin_1RB0LB_1LC1RD_0RD0LC_1RA0LA. rewrite epow2_1RB0LB_1LC1RD_0RD0LC_1RA0LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LB_1LC1RD_0RD0LC_1RA0LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LB_1LC1RD_0RD0LC_1RA0LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BM0_1RB0LB_1LC1RD_0RD0LC_1RA0LA.
Proof.
  intro j.
