  exists (6 * j + 18), (cden (Ap_Alph_000_001_1 q0 ++ [S0]) [] j A1_1RB0LB_1LC1RD_0RD0LC_1RA1LD).
  split; [lia|]. split; [| exact (gei_1RB0LB_1LC1RD_0RD0LC_1RA1LD p j q0 E)].
  rewrite (gsi_1RB0LB_1LC1RD_0RD0LC_1RA1LD p j q0 E).
  exact (srun_sound tm false true chi_1RB0LB_1LC1RD_0RD0LC_1RA1LD A0_1RB0LB_1LC1RD_0RD0LC_1RA1LD A1_1RB0LB_1LC1RD_0RD0LC_1RA1LD 6 18
           run_int_1RB0LB_1LC1RD_0RD0LC_1RA1LD (Ap_Alph_000_001_1 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
