Lemma epow22_1RB0LB_1LC1RD_0RD0LC_1RA1RB : forall n, Ap_Alph_000_001_00 (pow2 n) = rep [S0;S0;S0] n ++ [S0;S0].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI20_1RB0LB_1LC1RD_0RD0LC_1RA1RB : sconf := mkC StC (mkS [] [S0;S0;S1] 1 0 [S0;S0;S0]) S0 (mkS [] [] 0 0 []).
Definition AI21_1RB0LB_1LC1RD_0RD0LC_1RA1RB : sconf := mkC StC (mkS [] [S0;S0;S0] 1 0 [S0;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition chn2_1RB0LB_1LC1RD_0RD0LC_1RA1RB : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SCycR 3; SWin 1; SUnrotL 1].

Lemma run_inner2_1RB0LB_1LC1RD_0RD0LC_1RA1RB : srun tm false true chn2_1RB0LB_1LC1RD_0RD0LC_1RA1RB AI20_1RB0LB_1LC1RD_0RD0LC_1RA1RB = Some (AI21_1RB0LB_1LC1RD_0RD0LC_1RA1RB, 6, 6).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
