  exact (srun_sound tm false true chi_1RB0LB_1LC1RD_0RD0LC_1RA1RB A0_1RB0LB_1LC1RD_0RD0LC_1RA1RB A1_1RB0LB_1LC1RD_0RD0LC_1RA1RB 6 18
