Lemma geo_1RB0LB_1LC1RD_0RD0LC_1RA1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LB_1LC1RD_0RD0LC_1RA1RB) = lift (Cc (Pos.succ p)).
