(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LB_1LC1RD_0RD0LC_1RA1RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB0LB_1LC1RD_0RD0LC_1RA1RB p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 13), (cden [] [] j BB1_1RB0LB_1LC1RD_0RD0LC_1RA1RB).
      split; [lia|]. split; [| exact (gbo_1RB0LB_1LC1RD_0RD0LC_1RA1RB j)].
