(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LB_1RC0LC_1LD1RA_0RC0LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB0LB_1RC0LC_1LD1RA_0RC0LD p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 23), (cden [] [] j BB1_1RB0LB_1RC0LC_1LD1RA_0RC0LD).
      split; [lia|]. split; [| exact (gbo_1RB0LB_1RC0LC_1LD1RA_0RC0LD j)].
      rewrite (gso_1RB0LB_1RC0LC_1LD1RA_0RC0LD p j E).
      exact (srun_sound tm true true chb_1RB0LB_1RC0LC_1LD1RA_0RC0LD B0_1RB0LB_1RC0LC_1LD1RA_0RC0LD BB1_1RB0LB_1RC0LC_1LD1RA_0RC0LD 6 23
               run_boot_1RB0LB_1RC0LC_1LD1RA_0RC0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB0LB_1RC0LC_1LD1RA_0RC0LD p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (6 * j + 10), (cden [] [] j BM1_1RB0LB_1RC0LC_1LD1RA_0RC0LD).
      split; [| exact (gbo2_1RB0LB_1RC0LC_1LD1RA_0RC0LD j)].
      rewrite (gxi_1RB0LB_1RC0LC_1LD1RA_0RC0LD j).
      exact (srun_sound tm true true chm_1RB0LB_1RC0LC_1LD1RA_0RC0LD BM0_1RB0LB_1RC0LC_1LD1RA_0RC0LD BM1_1RB0LB_1RC0LC_1LD1RA_0RC0LD 6 10
               run_shift_1RB0LB_1RC0LC_1LD1RA_0RC0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (6 * j + 25), (cden [] [] j B1_1RB0LB_1RC0LC_1LD1RA_0RC0LD).
    split; [| exact (geo_1RB0LB_1RC0LC_1LD1RA_0RC0LD p j E)].
    rewrite (gxi2_1RB0LB_1RC0LC_1LD1RA_0RC0LD j).
    exact (srun_sound tm true true che_1RB0LB_1RC0LC_1LD1RA_0RC0LD BE0_1RB0LB_1RC0LC_1LD1RA_0RC0LD B1_1RB0LB_1RC0LC_1LD1RA_0RC0LD 6 25
             run_exit_1RB0LB_1RC0LC_1LD1RA_0RC0LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LB_1RC0LC_1LD1RA_0RC0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LB_1RC0LC_1LD1RA_0RC0LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LB_1RC0LC_1LD1RA_0RC0LD p j' E).
