(** ** The lap *)

Lemma lap_1RB0LB_1RC0RB_1LC1LD_1LA0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
