  - destruct (lapi_1RB0LB_1RC0RB_1LC1LD_1LA0LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0LB_1RC0RB_1LC1LD_1LA0LD B0_1RB0LB_1RC0RB_1LC1LD_1LA0LD B1_1RB0LB_1RC0RB_1LC1LD_1LA0LD 8 14 p j' [] []).
    + exact run_ovf_1RB0LB_1RC0RB_1LC1LD_1LA0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0LB_1RC0RB_1LC1LD_1LA0LD p j' E).
    + exact (geo_1RB0LB_1RC0RB_1LC1LD_1LA0LD p j' E).
    + lia.
Qed.

