(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LB_1RC1LB_0LA1RD_0LD0RC : list Instr := [].
Definition tmw_1RB0LB_1RC1LB_0LA1RD_0LD0RC : TM := tm_wrap_trs tm_1RB0LB_1RC1LB_0LA1RD_0LD0RC pins_1RB0LB_1RC1LB_0LA1RD_0LD0RC.
Local Notation tm := tmw_1RB0LB_1RC1LB_0LA1RD_0LD0RC.

Definition Cc_1RB0LB_1RC1LB_0LA1RD_0LD0RC (p : positive) : cconf := (StB, (Ap_Alph_10_11_11 p ++ [S0], S0, [])).
Local Notation Cc := Cc_1RB0LB_1RC1LB_0LA1RD_0LD0RC.

(** ** The certificate *)

Definition A0_1RB0LB_1RC1LB_0LA1RD_0LD0RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB0LB_1RC1LB_0LA1RD_0LD0RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chi_1RB0LB_1RC1LB_0LA1RD_0LD0RC : list lstep := [SWinR 2; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 5; SUnrotL 1].

Lemma run_int_1RB0LB_1RC1LB_0LA1RD_0LD0RC : srun tm false true chi_1RB0LB_1RC1LB_0LA1RD_0LD0RC A0_1RB0LB_1RC1LB_0LA1RD_0LD0RC = Some (A1_1RB0LB_1RC1LB_0LA1RD_0LD0RC, 4, 10).
