(** The chain into this family lands on its anchor up to 0/2
    trailing blanks. *)
Lemma gbo_1RB0LB_1RC1LB_0LA1RD_0LD0RC : forall j, lift (cden [] [] j BB1_1RB0LB_1RC1LB_0LA1RD_0LD0RC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0LB_1RC1LB_0LA1RD_0LD0RC = (StA, (rep [S1;S0] j ++ [S1;S1], S0, (([]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_1RB0LB_1RC1LB_0LA1RD_0LD0RC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_1RB0LB_1RC1LB_0LA1RD_0LD0RC. rewrite epow2_1RB0LB_1RC1LB_0LA1RD_0LD0RC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0LB_1RC1LB_0LA1RD_0LD0RC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0LB_1RC1LB_0LA1RD_0LD0RC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0LB_1RC1LB_0LA1RD_0LD0RC.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0LB_1RC1LB_0LA1RD_0LD0RC, cden, BE0_1RB0LB_1RC1LB_0LA1RD_0LD0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LB_1RC1LB_0LA1RD_0LD0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB0LB_1RC1LB_0LA1RD_0LD0RC. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LB_1RC1LB_0LA1RD_0LD0RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LB_1RC1LB_0LA1RD_0LD0RC p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_1RB0LB_1RC1LB_0LA1RD_0LD0RC).
    split; [lia|]. split; [| exact (gbo_1RB0LB_1RC1LB_0LA1RD_0LD0RC j)].
    rewrite (gso_1RB0LB_1RC1LB_0LA1RD_0LD0RC p j E).
    exact (srun_sound tm true true chb_1RB0LB_1RC1LB_0LA1RD_0LD0RC B0_1RB0LB_1RC1LB_0LA1RD_0LD0RC BB1_1RB0LB_1RC1LB_0LA1RD_0LD0RC 4 9
             run_boot_1RB0LB_1RC1LB_0LA1RD_0LD0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 15), (cden [] [] j B1_1RB0LB_1RC1LB_0LA1RD_0LD0RC).
    split; [| exact (geo_1RB0LB_1RC1LB_0LA1RD_0LD0RC p j E)].
    rewrite (gxi_1RB0LB_1RC1LB_0LA1RD_0LD0RC j).
    exact (srun_sound tm true true che_1RB0LB_1RC1LB_0LA1RD_0LD0RC BE0_1RB0LB_1RC1LB_0LA1RD_0LD0RC B1_1RB0LB_1RC1LB_0LA1RD_0LD0RC 4 15
             run_exit_1RB0LB_1RC1LB_0LA1RD_0LD0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LB_1RC1LB_0LA1RD_0LD0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LB_1RC1LB_0LA1RD_0LD0RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LB_1RC1LB_0LA1RD_0LD0RC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LB_1RC1LB_0LA1RD_0LD0RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 11.
  assert (H : match csteps tm 11 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 11 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LB_1RC1LB_0LA1RD_0LD0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LB_1RC1LB_0LA1RD_0LD0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LB_1RC1LB_0LA1RD_0LD0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LB_1RC1LB_0LA1RD_0LD0RC p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB0LB_1RC1LB_0LA1RD_0LD0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB0LB_1RC1LB_0LA1RD_0LD0RC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB0LB_1RC1LB_0LA1RD_0LD0RC p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB0LB_1RC1LB_0LA1RD_0LD0RC p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LB_1RC1LB_0LA1RD_0LD0RC : forall t, ~ In t pins_1RB0LB_1RC1LB_0LA1RD_0LD0RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LB_1RC1LB_0LA1RD_0LD0RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
