    apply (lap_of_run tm Cc true true cho_1RB0LB_1RC1LD_1LA1RA_0RD1RA B0_1RB0LB_1RC1LD_1LA1RA_0RD1RA B1_1RB0LB_1RC1LD_1LA1RA_0RD1RA 12 22 p j' [] []).
