(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0LC_0LA0RA_1RA1LD_1RB0LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_1RB0LC_0LA0RA_1RA1LD_1RB0LC /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_1RB0LC_0LA0RA_1RA1LD_1RB0LC = Cc (Pos.succ p).
