    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LA1RA_1LA1LD_0LC0RB [SWinR 2; SRotL 1; SWin 1; SCycL 2 0; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB0LC_0LA1RA_1LA1LD_0LC0RB (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB0LC_0LA1RA_1LA1LD_0LC0RB [SWinR 2; SRotL 1; SWin 1; SCycL 2 0; SWinL 2] (StC, S0) ltac:(vm_compute; reflexivity)
