(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0LC_0LA1RD_1RD1LA_0RB___ : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chb_1RB0LC_0LA1RD_1RD1LA_0RB___ : list lstep := [SWinR 2; SCycL 2 0; SWin 4; SCycR 2].

Lemma run_boot_1RB0LC_0LA1RD_1RD1LA_0RB___ : srun tm true true chb_1RB0LC_0LA1RD_1RD1LA_0RB___ B0_1RB0LC_0LA1RD_1RD1LA_0RB___ = Some (BB1_1RB0LC_0LA1RD_1RD1LA_0RB___, 4, 6).
