Lemma geo_1RB0LC_0LA1RD_1RD1LA_0RB___ : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0LC_0LA1RD_1RD1LA_0RB___) = lift (Cc (Pos.succ p)).
