(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0LC_0LA1RD_1RD1LA_0RB___ : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB0LC_0LA1RD_1RD1LA_0RB___. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0LC_0LA1RD_1RD1LA_0RB___ : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LC_0LA1RD_1RD1LA_0RB___ p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB0LC_0LA1RD_1RD1LA_0RB___).
    split; [lia|]. split; [| exact (gbo_1RB0LC_0LA1RD_1RD1LA_0RB___ j)].
    rewrite (gso_1RB0LC_0LA1RD_1RD1LA_0RB___ p j E).
    exact (srun_sound tm true true chb_1RB0LC_0LA1RD_1RD1LA_0RB___ B0_1RB0LC_0LA1RD_1RD1LA_0RB___ BB1_1RB0LC_0LA1RD_1RD1LA_0RB___ 4 6
             run_boot_1RB0LC_0LA1RD_1RD1LA_0RB___ [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 12), (cden [] [] j B1_1RB0LC_0LA1RD_1RD1LA_0RB___).
    split; [| exact (geo_1RB0LC_0LA1RD_1RD1LA_0RB___ p j E)].
    rewrite (gxi_1RB0LC_0LA1RD_1RD1LA_0RB___ j).
    exact (srun_sound tm true true che_1RB0LC_0LA1RD_1RD1LA_0RB___ BE0_1RB0LC_0LA1RD_1RD1LA_0RB___ B1_1RB0LC_0LA1RD_1RD1LA_0RB___ 4 12
             run_exit_1RB0LC_0LA1RD_1RD1LA_0RB___ [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0LC_0LA1RD_1RD1LA_0RB___ : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0LC_0LA1RD_1RD1LA_0RB___ p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0LC_0LA1RD_1RD1LA_0RB___ p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0LC_0LA1RD_1RD1LA_0RB___ : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 6.
  assert (H : match csteps tm 6 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 6 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0LC_0LA1RD_1RD1LA_0RB___ : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0LC_0LA1RD_1RD1LA_0RB___ = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0LC_0LA1RD_1RD1LA_0RB___ p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0LC_0LA1RD_1RD1LA_0RB___ p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB0LC_0LA1RD_1RD1LA_0RB___ : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB0LC_0LA1RD_1RD1LA_0RB___ = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB0LC_0LA1RD_1RD1LA_0RB___ t p (pow2 j)).
  - exists (4 * j + 6), (cden [] [] j BB1_1RB0LC_0LA1RD_1RD1LA_0RB___). split;
      [| exact (gbo_1RB0LC_0LA1RD_1RD1LA_0RB___ j)].
    rewrite (gso_1RB0LC_0LA1RD_1RD1LA_0RB___ p j E).
    exact (srun_sound tm true true chb_1RB0LC_0LA1RD_1RD1LA_0RB___ B0_1RB0LC_0LA1RD_1RD1LA_0RB___ BB1_1RB0LC_0LA1RD_1RD1LA_0RB___ 4 6
             run_boot_1RB0LC_0LA1RD_1RD1LA_0RB___ [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB0LC_0LA1RD_1RD1LA_0RB___ xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB0LC_0LA1RD_1RD1LA_0RB___ j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0LC_0LA1RD_1RD1LA_0RB___ : forall t, ~ In t pins_1RB0LC_0LA1RD_1RD1LA_0RB___ ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0LC_0LA1RD_1RD1LA_0RB___.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
