  apply (nested_overflow_lift tm Cc Cin lapin_1RB0LC_0LA1RD_1RD1LA_1LB0RB p (pow2 j)).
  - exists (6 * j + 6), (cden [] [] j BB1_1RB0LC_0LA1RD_1RD1LA_1LB0RB).
    split; [lia|]. split; [| exact (gbo_1RB0LC_0LA1RD_1RD1LA_1LB0RB j)].
    rewrite (gso_1RB0LC_0LA1RD_1RD1LA_1LB0RB p j E).
    exact (srun_sound tm true true chb_1RB0LC_0LA1RD_1RD1LA_1LB0RB B0_1RB0LC_0LA1RD_1RD1LA_1LB0RB BB1_1RB0LC_0LA1RD_1RD1LA_1LB0RB 6 6
             run_boot_1RB0LC_0LA1RD_1RD1LA_1LB0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 18), (cden [] [] j B1_1RB0LC_0LA1RD_1RD1LA_1LB0RB).
    split; [| exact (geo_1RB0LC_0LA1RD_1RD1LA_1LB0RB p j E)].
