(** ** The lap *)

Lemma lap_1RB0LC_0LA1RD_1RD1LA_1LB0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
