(** ** Bootstrap *)

Lemma boot_1RB0LC_0LA1RD_1RD1LA_1LB0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
