  apply (fire_via_fill tm Cc Cin lapin_1RB0LC_0LA1RD_1RD1LA_1LB0RB t p (pow2 j)).
  - exists (6 * j + 6), (cden [] [] j BB1_1RB0LC_0LA1RD_1RD1LA_1LB0RB). split;
      [| exact (gbo_1RB0LC_0LA1RD_1RD1LA_1LB0RB j)].
