    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0LC_0LA1RD_1RD1LA_1LB0RB [SWinR 2; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 4; SWin 1; SUnrotL 1; SRotL 1; SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB0LC_0LA1RD_1RD1LA_1LB0RB : NeverQuasiHaltsTr tm_1RB0LC_0LA1RD_1RD1LA_1LB0RB.
Proof.
  apply (glue_neverqhtr tm_1RB0LC_0LA1RD_1RD1LA_1LB0RB pins_1RB0LC_0LA1RD_1RD1LA_1LB0RB Cc 1).
