Lemma gp_1RB0LC_0LB0RC_0LD1RA_1RC1LD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_1RB0LC_0LB0RC_0LD1RA_1RC1LD /\
