Lemma lapi_1RB0LC_0LB0RC_0LD1RA_1RC1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0LC_0LB0RC_0LD1RA_1RC1LD p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0LC_0LB0RC_0LD1RA_1RC1LD Z0_1RB0LC_0LB0RC_0LD1RA_1RC1LD Z1_1RB0LC_0LB0RC_0LD1RA_1RC1LD 0 2
