(** 1RB0LC_0LB1LA_0RC1RD_1LB0RD *)
(** 1RB0LC_0LB1LA_0RC1RD_1LB0RD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0LC_0LB1LA_0RC1RD_1LB0RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S0 DL StB | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S0 DR StC | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S0 DR StD end.

(** Its mirror 1LB0RC_0RB1RA_0LC1LD_1RB0LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0LC_0LB1LA_0RC1RD_1LB0RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S0 DR StB | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DL StC | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S0 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0LC_0LB1LA_0RC1RD_1LB0RD : list Instr := [].
Definition tmw_1RB0LC_0LB1LA_0RC1RD_1LB0RD : TM := tm_wrap_trs tmm_1RB0LC_0LB1LA_0RC1RD_1LB0RD pins_1RB0LC_0LB1LA_0RC1RD_1LB0RD.
