  split; [lia|]. split; [| exact (gei_1RB0LC_0LC1LA_0RD1LB_1LC1RD p j q0 E)].
  rewrite (gsi_1RB0LC_0LC1LA_0RD1LB_1LC1RD p j q0 E).
  exact (srun_sound tm false true chi_1RB0LC_0LC1LA_0RD1LB_1LC1RD A0_1RB0LC_0LC1LA_0RD1LB_1LC1RD A1_1RB0LC_0LC1LA_0RD1LB_1LC1RD 6 26
