(** ** The lap *)

Lemma lap_1RB0LC_0LC1LA_0RD1LB_1LC1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
